import{c as o,Z as e,Q as i,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"送元二使安西","description":"","frontmatter":{"title":"送元二使安西","author":"王维","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/12.md","filePath":"books/shici/tangshi/12.md"}'),s={name:"books/shici/tangshi/12.md"};function u(h,a,q,c,p,d){const t=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="送元二使安西" tabindex="-1">送元二使安西 <a class="header-anchor" href="#送元二使安西" aria-label="Permalink to &quot;送元二使安西&quot;">​</a></h1><p><strong>[唐] <a href="/authors/wangwei.html">王维</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>渭城朝雨浥轻尘，客舍青青柳色新。 劝君更尽一杯酒，西出阳关无故人。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>元二：诗人的朋友，排行第二，名字不详</li><li>使：出使</li><li>安西：唐代安西都护府，在今新疆库车县一带</li><li>渭城：秦代咸阳城，汉代改称渭城，在今陕西省西安市西北</li><li>浥：湿润</li><li>轻尘：地面的尘土</li><li>客舍：旅馆</li><li>柳色新：柳树的颜色清新翠绿</li><li>更尽：再喝完</li><li>阳关：在今甘肃省敦煌市西南，是古代通往西域的关口</li><li>故人：老朋友</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>渭城早晨的细雨湿润了地面的尘土，旅馆周围的柳树显得格外清新翠绿。劝您再喝完这一杯酒，向西出了阳关之后就没有老朋友了。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是王维送别友人出使安西时所作，是唐代送别诗的千古绝唱，后来被谱入乐府，成为送别时必唱的《阳关三叠》。</p><p>首句&quot;渭城朝雨浥轻尘&quot;，写送别时的环境。早晨的细雨湿润了尘土，空气清新，为送别营造了一种清新而略带忧伤的氛围。</p><p>次句&quot;客舍青青柳色新&quot;，写送别时的景物。&quot;客舍&quot;点明送别的地点，&quot;柳色新&quot;既写出了春天的生机，又暗含&quot;柳&quot;与&quot;留&quot;的谐音，表达了挽留之情。古人有折柳送别的习俗，柳树的意象在这里具有双重含义。</p><p>后两句&quot;劝君更尽一杯酒，西出阳关无故人&quot;，是全诗的主旨所在。诗人以朴素的语言，表达了对友人的深情厚谊。&quot;更尽一杯酒&quot;，既是对友人的祝福，也是对离别的不舍。&quot;西出阳关无故人&quot;，则点明了离别后的孤独，阳关之外是荒凉的西域，友人将独自面对未知的旅程。</p><p>全诗语言平淡自然，却蕴含着深厚的情感，将离别之情写得真挚动人，成为千古传诵的送别名篇。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>王维</strong>（701年－761年），字摩诘，号摩诘居士，唐代著名诗人、画家，与孟浩然并称&quot;王孟&quot;，有&quot;诗佛&quot;之称。其诗清新淡远，自然脱俗，苏轼赞其&quot;诗中有画，画中有诗&quot;。</p><p><a href="/authors/wangwei.html">查看作者详情 →</a></p></blockquote>',17)),n(t)])}const b=o(s,[["render",u]]);export{m as __pageData,b as default};
